//! Conformance vectors for the vault format, generated by this (Rust) code.
//!
//! `conformance/rust/vault.json` pins every byte of the format with fixed,
//! test-only keys and a fixed random stream. This test regenerates the file in
//! memory and requires the committed copy to be identical, so a change to the
//! format cannot go unnoticed. To rewrite the file after a deliberate change:
//!
//! ```sh
//! MUSE_WRITE_VAULT_VECTORS=1 cargo test --test vault_vectors
//! ```
//!
//! `tests/test_vault_vectors.py` (Python, `cryptography` only) checks the same
//! file independently, so the format is not defined by one implementation.
//!
//! One vector per line: `{"name", "fn", "input", "expected"}`. Bytes are hex.

use std::fs;
use std::path::PathBuf;

use muse_core::vault::header::Header;
use muse_core::vault::mnemonic::{entropy_to_indices, entropy_to_words, words_to_entropy};
use muse_core::vault::primitives::{
    argon2id, bucket_size, export_identity_bytes, head_bucket, hkdf32, hmac256, index_tag, keyed_ref, kind_tag,
    normalise_index_value, open, pad_payload, seal, slot_private, subkey, unpad_payload, unwrap_from_slot,
    word_check_table, wrap_to_slot, x25519_public,
};
use muse_core::vault::record::{
    body_aad, head_aad, open_body, open_head, seal_body, seal_head, HeadMeta, HeadPlain, STATE_LIVE, STATE_TOMBSTONE,
};
use muse_core::vault::secret::{hex, sha256_hex, unhex};
use muse_core::vault::{
    Argon2Params, DeviceKeyStore, Language, MemoryKeyStore, MemoryStore, PassphraseKeyStore, RecoveryKey,
    RecoveryPolicy, Secret32, TestRng, Vault, VaultRng,
};
use serde_json::{json, Value};
use unicode_normalization::UnicodeNormalization;

const OFFICIAL: &str = include_str!("data/bip39_vectors.json");

struct Out(Vec<String>);

impl Out {
    fn push(&mut self, name: impl AsRef<str>, function: &str, input: Value, expected: Value) {
        let vector = json!({"name": name.as_ref(), "fn": function, "input": input, "expected": expected});
        self.0.push(serde_json::to_string(&vector).unwrap());
    }
}

fn take<const N: usize>(rng: &mut TestRng) -> [u8; N] {
    let mut out = [0u8; N];
    rng.fill(&mut out).unwrap();
    out
}

fn secret(rng: &mut TestRng) -> Secret32 {
    Secret32::new(take(rng))
}

fn store_json(store: &MemoryStore) -> Value {
    let records: serde_json::Map<String, Value> = store
        .records
        .iter()
        .map(|(id, r)| {
            (id.clone(), json!({"kind_tag": r.kind_tag, "index_tags": r.index_tags, "head": hex(&r.head), "body": hex(&r.body)}))
        })
        .collect();
    json!({"header": String::from_utf8(store.header.clone().unwrap()).unwrap(), "records": records})
}

fn build() -> String {
    let mut out = Out(Vec::new());
    let mut rng = TestRng::new(b"muse vault conformance vectors v1");

    // ---- HKDF: purpose keys under a master key.
    let purposes = ["record-wrap", "index", "ref", "header-mac", "words", "previous", "export-mac", "sync", "store"];
    for case in 0..3 {
        let vmk = secret(&mut rng);
        let vault_id: [u8; 16] = take(&mut rng);
        for purpose in purposes {
            out.push(
                format!("subkey: {purpose} #{case}"),
                "subkey",
                json!({"vmk": hex(vmk.expose()), "vault_id": hex(&vault_id), "purpose": purpose}),
                json!(hex(subkey(&vmk, &vault_id, purpose).expose())),
            );
        }
    }
    for (i, (salt, ikm, info)) in
        [(&b""[..], &b"ikm"[..], &b""[..]), (&b"salt"[..], &b"input key material"[..], &b"info"[..]), (&[0u8; 80][..], &[1u8; 32][..], &b"muse-vault/v1/slot-kek"[..])]
            .into_iter()
            .enumerate()
    {
        out.push(
            format!("hkdf32 #{i}"),
            "hkdf32",
            json!({"salt": hex(salt), "ikm": hex(ikm), "info": hex(info)}),
            json!(hex(hkdf32(salt, ikm, info).expose())),
        );
    }

    // ---- XChaCha20-Poly1305.
    for (i, (aad_len, len)) in [(0, 0), (0, 1), (12, 114), (33, 64), (5, 65), (64, 300), (1, 1000)].into_iter().enumerate() {
        let key = secret(&mut rng);
        let nonce: [u8; 24] = take(&mut rng);
        let aad: Vec<u8> = (0..aad_len).map(|n| n as u8).collect();
        let plaintext: Vec<u8> = (0..len).map(|n| (n * 7 % 251) as u8).collect();
        let boxed = seal(&key, &nonce, &aad, &plaintext);
        assert_eq!(open(&key, &nonce, &aad, &boxed).unwrap().as_slice(), plaintext.as_slice());
        out.push(
            format!("seal #{i}: {len} bytes"),
            "seal",
            json!({"key": hex(key.expose()), "nonce": hex(&nonce), "aad": hex(&aad), "plaintext": hex(&plaintext)}),
            json!(hex(&boxed)),
        );
    }

    // ---- Wrap slots: secret -> X25519 key; master key wrapped to it.
    for kind in ["device", "recovery", "prf"] {
        for case in 0..2 {
            let slot_secret = secret(&mut rng);
            let vault_id: [u8; 16] = take(&mut rng);
            let private = slot_private(&slot_secret, &vault_id, kind);
            let public = x25519_public(&private);
            out.push(
                format!("slot key: {kind} #{case}"),
                "slot_key",
                json!({"secret": hex(slot_secret.expose()), "vault_id": hex(&vault_id), "kind": kind}),
                json!({"private": hex(private.expose()), "public": hex(&public)}),
            );
            let (eph, nonce, vmk) = (secret(&mut rng), take::<24>(&mut rng), secret(&mut rng));
            let aad = format!("aad for {kind} #{case}").into_bytes();
            let (eph_public, wrapped) = wrap_to_slot(&eph, &nonce, &public, &aad, &vmk).unwrap();
            assert!(unwrap_from_slot(&private, &eph_public, &nonce, &aad, &wrapped).unwrap() == vmk);
            out.push(
                format!("slot wrap: {kind} #{case}"),
                "slot_wrap",
                json!({"eph": hex(eph.expose()), "nonce": hex(&nonce), "slot_public": hex(&public), "slot_private": hex(private.expose()),
                       "aad": hex(&aad), "vmk": hex(vmk.expose())}),
                json!({"eph_public": hex(&eph_public), "wrapped": hex(&wrapped)}),
            );
        }
    }

    // ---- Padding.
    let sizes = [0, 1, 255, 256, 257, 511, 512, 513, 1024, 4096, 4097, 32768, 65535, 65536, 65537, 131072, 131073, 1_000_000, 67_108_868];
    out.push("bucket_size", "bucket_size", json!(sizes), json!(sizes.iter().map(|&n| bucket_size(n)).collect::<Vec<_>>()));
    let head_sizes = [0, 1, 127, 128, 129, 192, 193, 1000];
    out.push("head_bucket", "head_bucket", json!(head_sizes), json!(head_sizes.iter().map(|&n| head_bucket(n)).collect::<Vec<_>>()));
    for len in [0usize, 1, 251, 252, 253, 600] {
        let payload: Vec<u8> = (0..len).map(|n| (n % 256) as u8).collect();
        let padded = pad_payload(&payload);
        assert_eq!(unpad_payload(&padded).unwrap().as_slice(), payload.as_slice());
        out.push(
            format!("pad_payload: {len} bytes"),
            "pad_payload",
            json!({"payload": hex(&payload)}),
            json!({"len": padded.len(), "sha256": sha256_hex(&padded), "first8": hex(&padded[..8])}),
        );
    }

    // ---- Blind index, kind tag, keyed reference.
    let texts = [
        "Tea", "  tea ", "ＴＥＡ", "烏龍茶", "\u{3000}烏龍茶", "Café", "cafe\u{301}", "ΣΟΦΟΣ", "ﬁsh", "İstanbul",
        "ｶﾞｲﾄﾞ", "한글", "ß", "", "a  b",
    ];
    for text in texts {
        out.push(format!("normalise: {text:?}"), "normalise_index_value", json!(text), json!(normalise_index_value(text)));
    }
    for case in 0..4 {
        let key = secret(&mut rng);
        for (kind, field, value) in [("memory", "topic", "Tea"), ("connector-token", "service", "行事曆"), ("receipt", "ref", ""), ("a", "b", "c")] {
            let value = normalise_index_value(value);
            out.push(
                format!("index_tag: {kind}/{field} #{case}"),
                "index_tag",
                json!({"k_index": hex(key.expose()), "kind": kind, "field": field, "value": value}),
                json!(index_tag(&key, kind, field, &value)),
            );
        }
        for kind in ["memory", "connector-token", "health.record"] {
            out.push(
                format!("kind_tag: {kind} #{case}"),
                "kind_tag",
                json!({"k_index": hex(key.expose()), "kind": kind}),
                json!(kind_tag(&key, kind)),
            );
        }
        for (label, data) in [("record", &b"abc"[..]), ("receipt", &b""[..]), ("", &b"x"[..])] {
            out.push(
                format!("keyed_ref: {label:?} #{case}"),
                "keyed_ref",
                json!({"k_ref": hex(key.expose()), "label": label, "data": hex(data)}),
                json!(hex(&keyed_ref(&key, label, data))),
            );
        }
    }
    out.push(
        "hmac256: RFC 4231 case 2",
        "hmac256",
        json!({"key": hex(b"Jefe"), "data": hex(b"what do ya want for nothing?")}),
        json!(hex(&hmac256(b"Jefe", &[b"what do ya ", b"want for nothing?"]))),
    );

    // ---- Mnemonics: the official test vectors (entropy <-> words), four languages.
    let official: Value = serde_json::from_str(OFFICIAL).unwrap();
    let mut official_count = 0;
    for language in Language::ALL {
        for (i, pair) in official["trezor"][language.name()].as_array().unwrap().iter().enumerate() {
            let (entropy, words) = (pair[0].as_str().unwrap(), pair[1].as_str().unwrap());
            let entropy_bytes = unhex(entropy).unwrap();
            // The published file joins every language with a plain space; ours shows Japanese with U+3000.
            let ours = entropy_to_words(language, &entropy_bytes).unwrap();
            let plain = |text: &str| text.replace('\u{3000}', " ").nfkd().collect::<String>();
            assert_eq!(plain(&ours), plain(words), "{} #{i}", language.name());
            assert_eq!(words_to_entropy(language, words).unwrap().as_slice(), entropy_bytes.as_slice());
            out.push(
                format!("mnemonic: {} official #{i}", language.name()),
                "mnemonic",
                json!({"language": language.name(), "entropy": entropy}),
                json!(*ours),
            );
            official_count += 1;
        }
    }
    for (i, pair) in official["japanese_bip32jp"].as_array().unwrap().iter().enumerate() {
        let (entropy, words) = (pair[0].as_str().unwrap(), pair[1].as_str().unwrap());
        let entropy_bytes = unhex(entropy).unwrap();
        assert_eq!(*entropy_to_words(Language::Japanese, &entropy_bytes).unwrap(), words, "japanese (bip32JP) #{i}");
        assert_eq!(words_to_entropy(Language::Japanese, words).unwrap().as_slice(), entropy_bytes.as_slice());
        out.push(
            format!("mnemonic: japanese bip32JP #{i}"),
            "mnemonic",
            json!({"language": "japanese", "entropy": entropy}),
            json!(words),
        );
        official_count += 1;
    }
    assert_eq!(official_count, 120);
    for language in Language::ALL {
        let digest = sha256_hex(language.list_text().as_bytes());
        out.push(format!("word list: {}", language.name()), "word_list_sha256", json!(language.name()), json!(digest));
    }

    // ---- Recovery key: word check values and the export recipient.
    for case in 0..4 {
        let entropy = secret(&mut rng);
        let salt: [u8; 16] = take(&mut rng);
        let indices: [u16; 24] = entropy_to_indices(entropy.expose()).unwrap().as_slice().try_into().unwrap();
        out.push(
            format!("word_check_table #{case}"),
            "word_check_table",
            json!({"salt": hex(&salt), "entropy": hex(entropy.expose()), "indices": indices.to_vec()}),
            json!(hex(word_check_table(&salt, &indices).as_slice())),
        );
        let recipient = RecoveryKey::from_entropy(entropy.clone()).export_recipient().unwrap();
        out.push(
            format!("export identity #{case}"),
            "export_identity",
            json!({"entropy": hex(entropy.expose())}),
            json!({"identity_bytes": hex(export_identity_bytes(&entropy).expose()), "recipient": recipient}),
        );
    }

    // ---- Argon2id and the passphrase key file.
    for (i, (passphrase, m_kib, t, p)) in [("password", 64, 1, 1), ("密碼 correct horse", 256, 2, 1), ("a passphrase", 19456, 2, 1)].into_iter().enumerate() {
        let salt: [u8; 16] = take(&mut rng);
        let key = argon2id(passphrase.as_bytes(), &salt, m_kib, t, p).unwrap();
        out.push(
            format!("argon2id #{i}: m={m_kib} t={t} p={p}"),
            "argon2id",
            json!({"passphrase": passphrase, "salt": hex(&salt), "m_kib": m_kib, "t": t, "p": p}),
            json!(hex(key.expose())),
        );
    }
    let (pass_store, key_file) = PassphraseKeyStore::create("密碼　ｃorrect horse", Argon2Params::MINIMUM, &mut rng).unwrap();
    let probe: [u8; 32] = take(&mut rng);
    let blob = pass_store.wrap(&probe).unwrap();
    assert_eq!(PassphraseKeyStore::open("密碼 correct horse", &key_file).unwrap().unwrap(&blob).unwrap().as_slice(), &probe);
    out.push(
        "key file: open with the passphrase, then unwrap the blob",
        "key_file",
        json!({"passphrase": "密碼 correct horse", "key_file": String::from_utf8(key_file).unwrap(), "blob": hex(&blob)}),
        json!(hex(&probe)),
    );
    for case in 0..3 {
        let key = secret(&mut rng);
        let slot_secret: [u8; 32] = take(&mut rng);
        let blob = MemoryKeyStore::from_key(key.clone()).wrap(&slot_secret).unwrap();
        out.push(
            format!("keystore wrap #{case}"),
            "keystore_wrap",
            json!({"key": hex(key.expose()), "secret": hex(&slot_secret)}),
            json!(hex(&blob)),
        );
    }

    // ---- Records: head and body.
    for (case, (kind, fields, payload, version, schema)) in [
        ("memory", vec![("topic", "tea")], "喜歡喝烏龍茶".as_bytes().to_vec(), 1u64, 1u32),
        ("connector-token", vec![("service", "calendar"), ("account", "a@example.org")], vec![0x5a; 300], 7, 2),
        ("receipt", vec![], Vec::new(), u64::MAX - 1, u32::MAX),
        ("health.record", vec![("code", &"x".repeat(200)[..])], (0..70_000u32).map(|n| (n % 253) as u8).collect(), 2, 0),
    ]
    .into_iter()
    .enumerate()
    {
        let (k_record, data_key) = (secret(&mut rng), secret(&mut rng));
        let (vault_id, record_id): ([u8; 16], [u8; 16]) = (take(&mut rng), take(&mut rng));
        let (head_nonce, body_nonce): ([u8; 24], [u8; 24]) = (take(&mut rng), take(&mut rng));
        let epoch = 1 + case as u64 * 3;
        let meta = HeadMeta { state: STATE_LIVE, version, schema, epoch };
        let plain = HeadPlain {
            data_key: data_key.clone(),
            kind: kind.to_string(),
            fields: fields.iter().map(|(n, v)| (n.to_string(), v.to_string())).collect(),
        };
        let head = seal_head(&k_record, &vault_id, &record_id, meta, &head_nonce, Some(&plain));
        let body = seal_body(&data_key, &vault_id, &record_id, meta, kind, &body_nonce, &payload);
        let (opened_meta, opened) = open_head(&k_record, &vault_id, &record_id, &head).unwrap();
        assert_eq!(opened_meta, meta);
        assert_eq!(open_body(&opened.unwrap().data_key, &vault_id, &record_id, meta, kind, &body).unwrap().as_slice(), payload.as_slice());
        let body_value = if body.len() > 2000 { json!({"len": body.len(), "sha256": sha256_hex(&body)}) } else { json!(hex(&body)) };
        let payload_value = if payload.len() > 2000 { json!({"pattern": "n % 253", "len": payload.len()}) } else { json!(hex(&payload)) };
        out.push(
            format!("record #{case}: {kind}"),
            "record",
            json!({"k_record": hex(k_record.expose()), "data_key": hex(data_key.expose()), "vault_id": hex(&vault_id),
                   "record_id": hex(&record_id), "state": 0, "version": version, "schema": schema, "epoch": epoch,
                   "kind": kind, "fields": fields, "payload": payload_value,
                   "head_nonce": hex(&head_nonce), "body_nonce": hex(&body_nonce)}),
            json!({"head": hex(&head), "body": body_value, "head_plain": hex(&plain.encode()),
                   "head_aad": hex(&head_aad(&vault_id, &record_id, meta)),
                   "body_aad": hex(&body_aad(&vault_id, &record_id, version, schema, kind))}),
        );
        let gone = HeadMeta { state: STATE_TOMBSTONE, version: version.wrapping_add(1), schema, epoch };
        let tombstone = seal_head(&k_record, &vault_id, &record_id, gone, &body_nonce, None);
        assert!(open_head(&k_record, &vault_id, &record_id, &tombstone).unwrap().1.is_none());
        out.push(
            format!("tombstone #{case}"),
            "tombstone",
            json!({"k_record": hex(k_record.expose()), "vault_id": hex(&vault_id), "record_id": hex(&record_id), "state": 1,
                   "version": gone.version, "schema": schema, "epoch": epoch, "head_nonce": hex(&body_nonce)}),
            json!({"head": hex(&tombstone), "head_aad": hex(&head_aad(&vault_id, &record_id, gone))}),
        );
    }

    // ---- A whole vault, step by step, from one fixed random stream.
    let keystore_key = [0x42u8; 32];
    let keystore = MemoryKeyStore::from_key(Secret32::new(keystore_key));
    let phone_key = [0x43u8; 32];
    let phone = MemoryKeyStore::from_key(Secret32::new(phone_key));
    let mut srng = TestRng::new(b"muse vault scenario v1");
    let now = 1_800_000_000u64;
    let (mut vault, recovery) = Vault::create(MemoryStore::new(), "laptop", &keystore, &mut srng, now).unwrap();
    let english = recovery.words(Language::English).to_string();
    let chinese = recovery.words(Language::ChineseTraditional).to_string();
    let words = |p: usize| recovery.word(Language::English, p).unwrap();
    assert!(vault.verify_recovery_words(Language::English, &[(2, words(2)), (9, words(9)), (23, words(23))], now + 1).unwrap());
    let memory = vault.put("memory", "喜歡喝烏龍茶".as_bytes(), 1, &[("topic", "Tea")], &mut srng).unwrap();
    let token = vault.put("connector-token", b"tok_live_123", 2, &[("service", "calendar")], &mut srng).unwrap();
    let gone = vault.put("memory", b"to be deleted", 1, &[], &mut srng).unwrap();
    vault.delete(&gone, &mut srng).unwrap();
    let request = Vault::<MemoryStore>::enroll_device(vault.vault_id(), "phone", &phone, &mut srng).unwrap();
    let phone_slot = vault.add_device_slot(&request, &mut srng, now + 2).unwrap();
    let prf_salt = Vault::<MemoryStore>::new_prf_salt(&mut srng).unwrap();
    let prf_output = [0x44u8; 32];
    let prf_slot = vault.add_prf_slot("passkey", b"credential-id", &prf_salt, &Secret32::new(prf_output), &mut srng, now + 3).unwrap();
    let records = json!({"memory": {"id": memory, "kind": "memory", "payload": hex("喜歡喝烏龍茶".as_bytes()), "schema": 1, "version": 1,
                                    "fields": [["topic", "tea"]]},
                         "token": {"id": token, "kind": "connector-token", "payload": hex(b"tok_live_123"), "schema": 2, "version": 1,
                                   "fields": [["service", "calendar"]]},
                         "deleted": {"id": gone}});
    let secrets = json!({"laptop_keystore_key": hex(&keystore_key), "phone_keystore_key": hex(&phone_key),
                         "prf_slot": prf_slot, "prf_output": hex(&prf_output),
                         "recovery_words_english": english, "recovery_words_chinese_traditional": chinese});
    let step1 = store_json(vault.store());
    let header1 = Header::parse(vault.store().header.as_ref().unwrap()).unwrap();
    out.push(
        "scenario 1: create, confirm words, three records (one deleted), a second device, a passkey",
        "scenario",
        json!({"seed": "muse vault scenario v1", "now": now, "test_only_secrets": secrets, "records": records, "epoch": 1}),
        json!({"store": step1, "header_transcript_sha256": sha256_hex(&header1.transcript())}),
    );
    let report = vault.lost_device(&phone_slot, RecoveryPolicy::Keep, &mut srng, now + 4).unwrap();
    assert_eq!((report.epoch, report.rewrapped, report.skipped), (2, 3, 0));
    assert!(report.new_recovery.is_none());
    let header2 = Header::parse(vault.store().header.as_ref().unwrap()).unwrap();
    out.push(
        "scenario 2: the phone is lost (slot removed, master key rotated, heads re-wrapped, same recovery words)",
        "scenario",
        json!({"after": "scenario 1", "now": now + 4, "test_only_secrets": secrets, "records": records, "epoch": 2,
               "removed_device": "phone"}),
        json!({"store": store_json(vault.store()), "header_transcript_sha256": sha256_hex(&header2.transcript())}),
    );
    let report = vault.rotate(RecoveryPolicy::Renew, &mut srng, now + 5).unwrap();
    let renewed = report.new_recovery.unwrap();
    let mut secrets3 = secrets.clone();
    secrets3["recovery_words_english"] = json!(*renewed.words(Language::English));
    secrets3["recovery_words_chinese_traditional"] = json!(*renewed.words(Language::ChineseTraditional));
    secrets3["old_recovery_words_english"] = secrets["recovery_words_english"].clone();
    let header3 = Header::parse(vault.store().header.as_ref().unwrap()).unwrap();
    out.push(
        "scenario 3: rotated again with new recovery words",
        "scenario",
        json!({"after": "scenario 2", "now": now + 5, "test_only_secrets": secrets3, "records": records, "epoch": 3}),
        json!({"store": store_json(vault.store()), "header_transcript_sha256": sha256_hex(&header3.transcript())}),
    );

    format!("[\n{}\n]\n", out.0.join(",\n"))
}

fn path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("conformance").join("rust").join("vault.json")
}

#[test]
fn committed_vectors_are_what_this_code_produces() {
    let fresh = build();
    assert_eq!(fresh, build(), "the generator must be deterministic");
    if std::env::var_os("MUSE_WRITE_VAULT_VECTORS").is_some() {
        fs::create_dir_all(path().parent().unwrap()).unwrap();
        fs::write(path(), &fresh).unwrap();
    }
    let committed = fs::read_to_string(path()).expect("core/conformance/rust/vault.json (see the top of this file)");
    assert!(
        committed == fresh,
        "core/conformance/rust/vault.json is not what this code produces. If the format was changed on purpose, \
         rewrite it with MUSE_WRITE_VAULT_VECTORS=1 and update docs/spec/interfaces/vault-format.md"
    );
    let vectors: Vec<Value> = serde_json::from_str(&committed).unwrap();
    let mut counts = std::collections::BTreeMap::new();
    for vector in &vectors {
        *counts.entry(vector["fn"].as_str().unwrap().to_string()).or_insert(0usize) += 1;
    }
    let expected = [
        ("argon2id", 3), ("bucket_size", 1), ("export_identity", 4), ("head_bucket", 1), ("hkdf32", 3), ("hmac256", 1),
        ("index_tag", 16), ("key_file", 1), ("keyed_ref", 12), ("keystore_wrap", 3), ("kind_tag", 12), ("mnemonic", 120),
        ("normalise_index_value", 15), ("pad_payload", 6), ("record", 4), ("scenario", 3), ("seal", 7), ("slot_key", 6),
        ("slot_wrap", 6), ("subkey", 27), ("tombstone", 4), ("word_check_table", 4), ("word_list_sha256", 4),
    ];
    let expected: std::collections::BTreeMap<String, usize> = expected.into_iter().map(|(k, v)| (k.to_string(), v)).collect();
    assert_eq!(counts, expected);
    assert_eq!(vectors.len(), 263);
}

/// The scenario stores in the committed file open with the keys the file
/// names, and hold the records it names: the vectors are usable as fixtures.
#[test]
fn scenario_stores_open_with_every_named_key() {
    let committed = fs::read_to_string(path()).unwrap();
    let vectors: Vec<Value> = serde_json::from_str(&committed).unwrap();
    let mut seen = 0;
    for vector in vectors.iter().filter(|v| v["fn"] == "scenario") {
        let (input, expected) = (&vector["input"], &vector["expected"]);
        let mut store = MemoryStore::new();
        store.header = Some(expected["store"]["header"].as_str().unwrap().as_bytes().to_vec());
        for (id, record) in expected["store"]["records"].as_object().unwrap() {
            store.records.insert(
                id.clone(),
                muse_core::vault::StoredRecord {
                    kind_tag: record["kind_tag"].as_str().unwrap().to_string(),
                    index_tags: record["index_tags"].as_array().unwrap().iter().map(|t| t.as_str().unwrap().to_string()).collect(),
                    head: unhex(record["head"].as_str().unwrap()).unwrap(),
                    body: unhex(record["body"].as_str().unwrap()).unwrap(),
                },
            );
        }
        let secrets = &input["test_only_secrets"];
        let key = |name: &str| Secret32::from_slice(&unhex(secrets[name].as_str().unwrap()).unwrap()).unwrap();
        let laptop = Vault::open_with_device(store.clone(), &MemoryKeyStore::from_key(key("laptop_keystore_key"))).unwrap();
        assert_eq!(laptop.epoch(), input["epoch"].as_u64().unwrap());
        let phone = Vault::open_with_device(store.clone(), &MemoryKeyStore::from_key(key("phone_keystore_key")));
        assert_eq!(phone.is_ok(), input["epoch"] == 1, "the phone opens the vault only before it is reported lost");
        for words in ["recovery_words_english", "recovery_words_chinese_traditional"] {
            let (recovery, _) = RecoveryKey::from_words_any(secrets[words].as_str().unwrap()).unwrap();
            assert!(Vault::open_with_recovery(store.clone(), &recovery).is_ok());
        }
        if let Some(old) = secrets["old_recovery_words_english"].as_str() {
            let recovery = RecoveryKey::from_words(Language::English, old).unwrap();
            assert!(Vault::open_with_recovery(store.clone(), &recovery).is_err());
        }
        assert!(Vault::open_with_prf(store.clone(), secrets["prf_slot"].as_str().unwrap(), &key("prf_output")).is_ok());
        for name in ["memory", "token"] {
            let wanted = &input["records"][name];
            let got = laptop.get(wanted["id"].as_str().unwrap()).unwrap();
            assert_eq!(hex(&got.payload), wanted["payload"].as_str().unwrap());
            assert_eq!(got.kind, wanted["kind"].as_str().unwrap());
            assert_eq!(laptop.list(&got.kind).unwrap(), vec![got.id.clone()]);
        }
        assert_eq!(laptop.find("memory", "topic", "TEA").unwrap().len(), 1);
        assert!(laptop.get(input["records"]["deleted"]["id"].as_str().unwrap()).is_err());
        seen += 1;
    }
    assert_eq!(seen, 3);
}
